import SwiftUI
import UIKit

struct Room:Identifiable,Hashable {
    var id:String
    var title:String
    var thread:String?
    var group:String?
    var avatar:String=""
    var owner:String=""
    var open=true
    var peer:String=""
}
struct ChatsScreen:View {
    @EnvironmentObject private var api:Backend
    @Environment(\.dismiss) private var dismiss
    @Environment(\.scenePhase) private var phase
    @State private var threads:[Item]=[],groups:[Item]=[],results:[Item]=[]
    @State private var settings=Item(),search="",error="",create=false
    @State private var destination:Room?
    var body:some View{List{LoadError(text:error);if !settings.flag("chat_enabled"){EmptyState(title:"الدردشة موقوفة من المدير",symbol:"bubble.left.and.exclamationmark.bubble.right")}else{
        if !search.isEmpty{Section("نتائج البحث"){ForEach(results){person in TaskButton(title:person.text("display_name"),symbol:"person.crop.circle"){let value=try await api.rpc("chat_open",["other":person.id]);guard let thread=value as? String else{throw FamilyError(text:"تعذّر فتح المحادثة.")};destination=Room(id:thread,title:person.text("display_name"),thread:thread,avatar:person.text("avatar_path"),peer:person.id)}};if results.isEmpty{Text("لا توجد أسماء مطابقة").foregroundStyle(.secondary)}}}
        if settings.flag("public_chat_enabled"){NavigationLink(value:Room(id:"public",title:"دردشة العائلة العامة")){Label("دردشة العائلة العامة",systemImage:"person.3.fill").padding(.vertical,8)}}
        Section("محادثاتي"){ForEach(threads){t in NavigationLink(value:Room(id:t.id,title:t.text("display_name"),thread:t.id,avatar:t.text("avatar_path"),peer:t.text("member_id"))){HStack(spacing:12){Avatar(path:t.text("avatar_path"),name:t.text("display_name"),size:48);VStack(alignment:.leading,spacing:5){Text(t.text("display_name")).font(.subheadline.bold());Text(t.text("last_body")).lineLimit(1).font(.caption).foregroundStyle(.secondary)};Spacer();if !t.text("last_at").isEmpty{Text(dateValue(t.text("last_at")),style:.time).font(.caption2).foregroundStyle(.secondary)}}.padding(.vertical,8)}};if threads.isEmpty{Text("ابحث عن أحد أفراد العائلة لبدء محادثة.").font(.footnote).foregroundStyle(.secondary)}}
        Section("المجموعات والأحداث"){ForEach(groups){g in NavigationLink(value:Room(id:g.id,title:g.text("title"),group:g.id,owner:g.text("owner_id"),open:g.flag("open_now"))){Label{VStack(alignment:.leading){Text(g.text("title"));if g.text("kind")=="event"{Text(g.flag("open_now") ? "الحدث جارٍ":"خارج موعد الحدث").font(.caption).foregroundStyle(.secondary)}}}icon:{Image(systemName:g.text("kind")=="event" ? "calendar":"person.3")}.padding(.vertical,8)}}}
        if settings.flag("restrict_gender_chat"){Text("تظهر الأسماء والمحادثات المسموح بها وفق ضوابط المدير.").font(.caption).foregroundStyle(.secondary)}
    }}.listStyle(.plain).scrollIndicators(.hidden).searchable(text:$search,prompt:"الاسم الأول أو رقم الجوال").navigationTitle("الدردشات").navigationBarTitleDisplayMode(.large).toolbar{ToolbarItem(placement:.cancellationAction){Button("الأخبار"){dismiss()}};if api.admin || settings.flag("allow_groups"){ToolbarItem(placement:.navigationBarTrailing){Button{create=true}label:{Image(systemName:"square.and.pencil")}.accessibilityLabel("إنشاء مجموعة")}}}.navigationDestination(for:Room.self){room in ChatRoom(room:room)}.navigationDestination(item:$destination){room in ChatRoom(room:room)}.sheet(isPresented:$create){NavigationStack{CreateGroupScreen{room in create=false;destination=room;Task{await load()}}}}.refreshable{await load()}.task{await load();while !Task.isCancelled{do{try await Task.sleep(nanoseconds:7_000_000_000)}catch{break};if phase == .active && api.active{await load()}}}.task(id:search){do{try await Task.sleep(nanoseconds:250_000_000);try Task.checkCancellation();let term=search.trimmingCharacters(in:.whitespacesAndNewlines);guard !term.isEmpty else{results=[];return};let data=try await api.rpc("chat_search",["term":term]);try Task.checkCancellation();results=Item.items(data)}catch{if !Task.isCancelled{self.error=api.errorText(error)}}}}
    func load()async{do{settings=(try await api.table("family_settings",[q("select","*"),q("id","eq.true")])).first ?? Item();guard settings.flag("chat_enabled") else{threads=[];groups=[];results=[];return};threads=Item.items(try await api.rpc("chat_list"));groups=Item.items(try await api.action("group_action","list"));error=""}catch{self.error=api.errorText(error)}}
}
struct ChatRoom:View {
    @EnvironmentObject private var api:Backend
    @Environment(\.scenePhase) private var phase
    let room:Room
    @State private var messages:[Item]=[],bodyText="",error="",search=""
    @State private var searchMode=false,more=true,sending=false,loading=false,details=false
    @State private var reply:Item?,editing:Item?,deleting:Item?
    @State private var open=true
    @FocusState private var focused:Bool
    var body:some View{VStack(spacing:0){if searchMode{TextField("بحث في الرسائل",text:$search).textFieldStyle(.roundedBorder).padding(10)};LoadError(text:error)
        ScrollViewReader{proxy in ScrollView{LazyVStack(spacing:7){if more && search.isEmpty{TaskButton(title:"رسائل أقدم",symbol:"arrow.up"){await load(older:true)}};if messages.isEmpty{Text("ابدأ الحديث بكلمة طيبة.").font(.footnote).foregroundStyle(.secondary).padding(30)};ForEach(messages){m in MessageBubble(message:m,mine:m.text("sender_id")==api.user.id).id(m.id).contextMenu{Button("نسخ",systemImage:"doc.on.doc"){UIPasteboard.general.string=m.text("body")};if m.text("deleted_at").isEmpty{Button("رد",systemImage:"arrowshape.turn.up.left"){reply=m;focused=true};if m.text("sender_id")==api.user.id{Button("تعديل",systemImage:"pencil"){editing=m};Button("حذف للجميع",systemImage:"trash",role:.destructive){deleting=m}}}}};Color.clear.frame(height:1).id("latest")}.padding(12)}.scrollIndicators(.hidden).scrollDismissesKeyboard(.interactively).background(Color(.systemGroupedBackground)).onChange(of:messages.last?.id){_ in if !loading{withAnimation{proxy.scrollTo("latest",anchor:.bottom)}}}}
    }.safeAreaInset(edge:.bottom){VStack(spacing:0){if let r=reply{HStack{VStack(alignment:.leading){Text(r.text("display_name")).font(.caption.bold());Text(r.text("body")).lineLimit(2).font(.caption)};Spacer();Button{reply=nil}label:{Image(systemName:"xmark.circle")}}.padding(12).background(brandBlue.opacity(0.08))};if open{HStack(alignment:.bottom,spacing:10){TextField("رسالة",text:$bodyText,axis:.vertical).lineLimit(1...5).padding(11).background(Color(.systemBackground),in:RoundedRectangle(cornerRadius:22)).focused($focused);TaskButton(title:"",symbol:"paperplane.fill"){let text=bodyText.trimmingCharacters(in:.whitespacesAndNewlines);guard !text.isEmpty,text.count<=2000 else{throw FamilyError(text:"الرسالة من حرف إلى 2000 حرف.")};if let r=reply{_ = try await api.action("message_action","reply_send",["id":r.raw["id"] ?? r.id,"message":text])}else if let group=room.group{_ = try await api.action("group_action","send",["id":group,"message":text])}else{_ = try await api.rpc("chat_send",["thread":room.thread.map { $0 as Any } ?? NSNull(),"message":text])};bodyText="";reply=nil;await load()}.disabled(bodyText.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty).padding(8).foregroundStyle(.white).background(brandBlue,in:Circle()).accessibilityLabel("إرسال الرسالة")}.padding(10)}else{Text("المحادثة غير متاحة حاليًا وفق الإعدادات أو موعد الحدث.").font(.footnote).padding()}}.background(.bar)}.navigationTitle(room.title).navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItemGroup(placement:.navigationBarTrailing){Button{searchMode.toggle();if !searchMode{search=""}}label:{Image(systemName:"magnifyingglass")}.accessibilityLabel("بحث في المحادثة");if room.group != nil{Button{details=true}label:{Image(systemName:"info.circle")}}else if !room.peer.isEmpty{NavigationLink{MemberScreen(member:room.peer)}label:{Image(systemName:"person.crop.circle")}}}}.sheet(isPresented:$details){NavigationStack{GroupDetails(room:room)}}.sheet(item:$editing){m in NavigationStack{MessageEditor(message:m){await load()}}}.confirmationDialog("حذف الرسالة للجميع؟",isPresented:Binding(get:{deleting != nil},set:{if !$0{deleting=nil}})){Button("حذف",role:.destructive){guard let m=deleting else{return};deleting=nil;Task{do{_ = try await api.action("message_action","delete",["id":m.raw["id"] ?? m.id]);await load()}catch{self.error=api.errorText(error)}}}}.task{open=room.open;await load();while !Task.isCancelled{do{try await Task.sleep(nanoseconds:5_000_000_000)}catch{break};if phase == .active && search.isEmpty{await load()}}}.task(id:search){do{try await Task.sleep(nanoseconds:250_000_000);try Task.checkCancellation();if search.isEmpty{await load();return};let p:[String:Any]=["thread":room.thread.map { $0 as Any } ?? NSNull(),"group":room.group.map { $0 as Any } ?? NSNull(),"term":search];let r=Item.items(try await api.action("message_action","search",p));try Task.checkCancellation();messages=r}catch{if !Task.isCancelled{self.error=api.errorText(error)}}}}
    func load(older:Bool=false)async{guard api.active else{return};do{let before:Any=older ? (messages.first?.raw["id"] ?? NSNull()):NSNull();let data:Any;if let group=room.group{data=try await api.action("group_action","read",["id":group,"before_id":before])}else{data=try await api.rpc("chat_read",["thread":room.thread.map { $0 as Any } ?? NSNull(),"before_id":before])};let r=Item.items(data);loading=older;if older{let known=Set(messages.map(\.id));messages=r.filter{!known.contains($0.id)}+messages;more=r.count==50}else if search.isEmpty{if messages.count>50,let last=messages.last, r.contains(where:{$0.id==last.id}){let fresh=Dictionary(uniqueKeysWithValues:r.map{($0.id,$0)});messages=messages.map{fresh[$0.id] ?? $0};let known=Set(messages.map(\.id));messages += r.filter{!known.contains($0.id)}}else{messages=r;more=r.count==50}};loading=false;error="";open=true}catch{open=false;self.error=api.errorText(error)}}
}
struct MessageBubble:View {let message:Item;let mine:Bool;var body:some View{HStack{if mine{Spacer(minLength:45)};VStack(alignment:.leading,spacing:4){if !mine{Text(message.text("display_name")).font(.caption2.bold()).foregroundStyle(brandBlue)};if !message.text("reply_excerpt").isEmpty{Text(message.text("reply_excerpt")).font(.caption).lineLimit(3).padding(7).frame(maxWidth:.infinity,alignment:.leading).background(Color.primary.opacity(0.04),in:RoundedRectangle(cornerRadius:6))};Text(message.text("body")).font(.body).textSelection(.enabled);HStack{Spacer(minLength:0);if !message.text("edited_at").isEmpty{Text("تم التعديل")};Text(dateValue(message.text("created_at")),style:.time)}.font(.system(size:10)).foregroundStyle(.secondary)}.padding(.horizontal,11).padding(.vertical,8).background(mine ? brandBlue.opacity(0.13):Color(.systemBackground),in:RoundedRectangle(cornerRadius:12));if !mine{Spacer(minLength:45)}}.privacySensitive()}}
struct MessageEditor:View {@EnvironmentObject private var api:Backend;@Environment(\.dismiss)private var dismiss;let message:Item;let saved:()async->Void;@State private var text="";var body:some View{Form{TextField("الرسالة",text:$text,axis:.vertical).lineLimit(3...10);TaskButton(title:"حفظ التعديل",symbol:"checkmark"){guard !text.trimmingCharacters(in:.whitespaces).isEmpty,text.count<=2000 else{return};_ = try await api.action("message_action","edit",["id":message.raw["id"] ?? message.id,"message":text]);await saved();dismiss()};Text("التعديل خلال 15 دقيقة من الإرسال.").font(.caption)}.navigationTitle("تعديل الرسالة").toolbar{ToolbarItem(placement:.cancellationAction){Button("إلغاء"){dismiss()}}}.task{text=message.text("body")}}}
struct CreateGroupScreen:View {
    @EnvironmentObject private var api:Backend
    @Environment(\.dismiss)private var dismiss
    let created:(Room)->Void
    @State private var title="",term="",kind="group",members:[Item]=[],results:[Item]=[],start=Date(),end=Date().addingTimeInterval(3600)
    var body:some View{Form{Section{TextField("اسم المجموعة",text:$title);if api.admin{Picker("النوع",selection:$kind){Text("مجموعة").tag("group");Text("حدث محدد").tag("event")}};if kind=="event"{DatePicker("البداية",selection:$start);DatePicker("النهاية",selection:$end)}};Section("إضافة أعضاء"){TextField("الاسم أو رقم الجوال",text:$term).task(id:term){do{try await Task.sleep(nanoseconds:250_000_000);guard !term.isEmpty else{results=[];return};let r=Item.items(try await api.rpc("chat_search",["term":term]));try Task.checkCancellation();results=r}catch{}};ForEach(results){p in Button{if members.contains(where:{$0.id==p.id}){members.removeAll{$0.id==p.id}}else if members.count<200{members.append(p)}}label:{Label(p.text("display_name"),systemImage:members.contains(where:{$0.id==p.id}) ? "checkmark.circle.fill":"circle")}};Text("المحددون: \(members.count)").font(.caption)};Section{TaskButton(title:"إنشاء",symbol:"plus"){guard title.count>=3,title.count<=100 else{throw FamilyError(text:"اسم المجموعة من 3 إلى 100 حرف.")};var p:[String:Any]=["title":title,"kind":kind,"members":members.map(\.id)];if kind=="event"{guard end>start else{throw FamilyError(text:"نهاية الحدث بعد بدايته.")};p["starts_at"]=ISO8601DateFormatter().string(from:start);p["ends_at"]=ISO8601DateFormatter().string(from:end)};guard let id=try await api.action("group_action","create",p) as? String else{throw FamilyError(text:"تعذّر إنشاء المجموعة.")};created(Room(id:id,title:title,group:id,owner:api.user.id));dismiss()}}}.scrollIndicators(.hidden).navigationTitle("محادثة جديدة").toolbar{ToolbarItem(placement:.cancellationAction){Button("إلغاء"){dismiss()}}}}
}
struct GroupDetails:View {
    @EnvironmentObject private var api:Backend;@Environment(\.dismiss)private var dismiss;let room:Room
    @State private var members:[Item]=[],results:[Item]=[],term="",error=""
    var manager:Bool{api.admin || room.owner==api.user.id}
    func load()async{do{members=Item.items(try await api.action("group_action","members",["id":room.id]));error=""}catch{self.error=api.errorText(error)}}
    var body:some View{List{LoadError(text:error);Section("الأعضاء"){ForEach(members){p in NavigationLink{MemberScreen(member:p.id)}label:{Text(p.text("display_name"))}.swipeActions{if manager && p.id != room.owner{Button("إزالة",role:.destructive){Task{do{_ = try await api.action("group_action","remove",["id":room.id,"member":p.id]);await load()}catch{self.error=api.errorText(error)}}}}}};if manager{Section("إضافة عضو"){TextField("الاسم أو رقم الجوال",text:$term).task(id:term){do{try await Task.sleep(nanoseconds:250_000_000);guard !term.isEmpty else{results=[];return};let r=Item.items(try await api.rpc("chat_search",["term":term]));try Task.checkCancellation();results=r}catch{}};ForEach(results){p in TaskButton(title:p.text("display_name"),symbol:"person.badge.plus"){_ = try await api.action("group_action","add",["id":room.id,"member":p.id]);await load()}}}};if room.owner != api.user.id{TaskButton(title:"مغادرة المجموعة",symbol:"rectangle.portrait.and.arrow.right"){_ = try await api.action("group_action","leave",["id":room.id]);dismiss()}}}.navigationTitle(room.title).toolbar{ToolbarItem(placement:.cancellationAction){Button("إغلاق"){dismiss()}}}.task{await load()}}
}
